	"gift_premium_subtitle": "Ajándékozz egy évnyi %1$s előfizetést %2$s felhasználónak %3$s időre. A fizetést követően értesítést kap majd, hogy ajándékot küldtél neki.",
	"gift_premium_terms_footer": "Az ajándék előfizetés díját a vásárláskor felszámítjuk, és az nem visszatérítendő. Ez egy egyszer használatos, nem kicserélhető, mással nem összevonható előfizetés, és nincs pénzbeli értéke. Azután kezdődik meg a használati időszak, hogy az X ellenőrizte a jogosultságot, és hozzárendelte azt a címzetthez, akinek el kell fogadnia az irányelveket és a következőt: %1$s. Ha a címzett nem felel meg a jogosultsági feltételek valamelyikének, lemondja az előfizetést vagy elutasítja a használati feltételeket és irányelveket, az ajándék nem váltható vissza és a díját nem térítjük vissza. Adók lehetnek érvényben. A feltételek változhatnak. %2$s",
