	"golive__tip_broadcaster_1": "<b>TIPP:</b> Köszönjük, hogy élőben közvetítesz. Üdvözöld az embereket, amikor csatlakoznak a videódhoz.",
	"golive__tip_broadcaster_10": "<b>TIPP:</b> Köszönjük, hogy élőben közvetítettél az X-en! ≺3",
	"golive__tip_broadcaster_2": "<b>TIPP:</b> Próbáld meg név szerint üdvözölni az embereket, amikor csatlakoznak az élő videódhoz. Imádni fogják.",
	"golive__tip_broadcaster_3": "<b>TIPP:</b> Legalább pár percig közvetíts élőben, hogy az emberek könnyebben megtalálhassanak.",
	"golive__tip_broadcaster_4": "<b>TIPP:</b> Kérdezd meg a nézőket, hogy hol élnek. Ez nagyszerű lehetőséget jelent a beszélgetés fellendítéséhez.",
	"golive__tip_broadcaster_5": "<b>TIPP:</b> Köszönd meg az embereknek a megtekintést, és válaszolj a hozzászólásaikra, hogy továbbra is nézzenek.",
	"golive__tip_broadcaster_6": "<b>TIPP:</b> Ha megszakad a kapcsolat a közvetítés során, akkor keress egy helyet, ahol jobb a jelerősség.",
	"golive__tip_broadcaster_7": "<b>TIPP:</b> Kérd meg az embereket, hogy kövessenek, így értesítést kaphatnak legközelebb, amikor élőben jelentkezel.",
	"golive__tip_broadcaster_8": "<b>TIPP:</b> Kezdd az élő videód egy gyors köszönéssel. A későbbi nézők imádni fogják.",
	"golive__tip_broadcaster_9": "<b>TIPP:</b> Köszönd meg nézőidnek a figyelmet élő videód befejezése előtt.",
	"golive__tip_pre_broadcast_1": "<b>TIPP:</b> Élő közvetítés előtt adj nevet a videónak, hogy az emberek könnyebben megtalálhassák.",
	"golive__tip_pre_broadcast_2": "<b>TIPP:</b> Ha beszédes címet adsz a videódnak, akkor az emberek jobban megértik, miről is szól.",
	"golive__tip_pre_broadcast_3": "<b>TIP:</b> Ötletekre van szükséged? Tarts bemutatót, oszd meg az ötleteidet vagy beszélgess olyan témákról, amik érdekelnek.",
	"golive__tip_pre_broadcast_4": "<b>TIPP:</b> Élő közvetítés előtt ügyelj rá, hogy megfelelő legyen a térerő.",
	"golive__tip_pre_broadcast_5": "<b>TIPP:</b> Adj címkét a címhez, hogy az emberek felfedezhessék az élő videódat.",
	"golive__tip_pre_broadcast_6": "<b>TIPP:</b> Ezek voltak a tippjeink mára. Köszönjük, hogy élőben közvetítesz az X-en.",
