	"identity_education_conditions": "Hozzájárulok, hogy X és az Au10tix felhasználja a személyi azonosítómról készült képeket és a szelfimet, beleértve a kivont biometrikus adatokat is, a személyazonosságom megerősítésére és az X kapcsolódó biztonsági céljaira, beleértve a megszemélyesítés megakadályozását. Az Au10tix legfeljebb 30 napig tárolhatja ezeket az adatokat. {{}}Tudj meg többet!{{}}",
	"identity_education_conditions_age_verification": "Hozzájárulok ahhoz, hogy az X és a Persona a személyi igazolványomat és a fényképemet felhasználja az életkorom megerősítésére. A fényképedet nem tároljuk el. Az X és a xAI megőrizheti az életkorodra vonatkozó információkat. {{}}Tudj meg többet!{{}}",
	"identity_education_conditions_eea": "\"Hozzájárulok ahhoz, hogy az X a személyazonosságom megerősítése céljából megossza a Au10tix vállalattal az azonosító okmányomról készült képeket, beleértve a biometrikus adatokat is, valamint a profilomból származó személyes adatokat.\n Hozzájárulok továbbá ahhoz, hogy az X legfeljebb 30 napig tárolja az azonosító okmányom képeit, beleértve a biometrikus adatokat is, és a képeket, valamint a profilomból származó adatokat biztonsági célokra használja fel, beleértve a megszemélyesítés megakadályozását is. {{}}Tudj meg többet{{}}!\"",
	"identity_education_conditions_persona_vendor": "Hozzájárulok ahhoz, hogy X és a Persona felhasználja a személyi azonosítómról készült képeket és a szelfimet, beleértve a kivont biometrikus adatokat is, személyazonosságom megerősítésére, valamint az X kapcsolódó biztonsági, csalásmegelőzési és fizetési céljaira. A Persona legfeljebb 30 napig tárolhatja ezeket az adatokat. Az X a teljes nevemet, címemet és a személyiazonosító-számom számjeleit mindaddig tárolhatja, amíg előfizetek az X Premium szolgáltatásra. {{}}Tudj meg többet!{{}}",
