	"payment_funds_insurance_footer_text": "\"A befizetéseidet a Cross River Bank őrzi, és az FDIC biztosítja őket akár 250 000 dollárig személyenként és jogi entitásonként. Ez az adott banknál, azonos számlatulajdonosi kategóriában vezetett összes számlára együtt értendő – még a képviseleti számlákra is.\n\"",
