	"tipjar_input_rationale_kakao_pay": "\"A felhasználók a fent megadott QR-hivatkozásra küldik a borravalót.\nA QR-hivatkozás megadásával és a borravaló elfogadásával felfedheted a fizetési szolgáltatásban megadott adataidat mások előtt, beleértve a nevedet, az e-mail-címedet és az egyéb adataidat is.\n\nA Kakao Pay QR-kód hivatkozása a KakaoTalk Továbbiak > Scanner részén található meg a jobb felső menü Pénzkód > Vágólapi kép ikonja alatt. Koppints az ikonra a hivatkozás vágólapra való másolásához, majd illeszd be a hivatkozást fentre.\"",
