	"toxic_reply_nudge_expanded_description_injunctive_norm_line_2": "Arra kérjük a felhasználókat, hogy olvassák át a potenciálisan sértő vagy káros bejegyzéseket. Át szeretnéd nézni a bejegyzést a posztolás előtt?",
	"toxic_reply_nudge_expanded_description_loss_frame_line_1": "A hasonló bejegyzések lejjebb kerülhetnek a beszélgetésben, és kevesebb ember láthatja őket.",
	"toxic_reply_nudge_expanded_description_loss_frame_line_2": "Arra kérjük a felhasználókat, hogy olvassák át a potenciálisan sértő vagy káros válaszokat. Át szeretnéd nézni a bejegyzést a posztolás előtt?",
