	"toxic_reply_nudge_expanded_title_descriptive_norm": "A legtöbb posztoló nem tesz közzé hasonló válaszokat",
	"toxic_reply_nudge_expanded_title_injunctive_norm": "Úgy posztolj másoknak, ahogyan szeretnéd, hogy ők posztoljanak neked.",
